#include <random>
#include <iostream>
#include <initializer_list>

int main() {
    std::discrete_distribution<int> dist = {0.1, 0.2, 0.7};  // Uses initializer_list<double>
    std::mt19937 gen;
    for (int i = 0; i < 5; ++i) {
        std::cout << dist(gen) << std::endl;  // Generates numbers based on weights
    }
    return 0;
}
